var TITLE = "[Sion] SAT Grammar";var QUIZ_KEY = "quiz_satgrammar_20_2026-09-11_v1";var ATT_KEY = "quiz_satgrammar_20_att_2026-09-11_v1";var REPORT_ENDPOINT = 'https://script.google.com/macros/s/AKfycbzRYITi7Q4ttOMcqHPBQ_mfc1m-Oyk_ne-7OKeRGbR_WFEUAe9oCKiC9E7f3ymZWR6i/exec';var RAW_QUESTIONS = [{"context": "The negotiations continued long into the night. Neither delegation was willing to compromise on the tariff provisions.", "stem": "Which choice most effectively combines the two sentences?", "opts": ["The negotiations continued long into the night; neither delegation was willing to compromise on the tariff provisions.", "The negotiations continued long into the night neither delegation was willing to compromise on the tariff provisions.", "The negotiations continued long into the night: neither delegation was willing to compromise on the tariff provisions.", "The negotiations continued long into the night, neither delegation was willing to compromise on the tariff provisions."], "ci": 0, "exp": "Both clauses are independent and closely related, so a semicolon is the most effective way to join them without a coordinating conjunction. A comma alone creates a comma splice, and no punctuation creates a run-on."}, {"context": "The report, along with several supporting appendices, _____ submitted to the board for final review.", "stem": "Which choice completes the sentence with the correct verb?", "opts": ["were", "was", "have been", "are"], "ci": 1, "exp": "The subject of the sentence is the singular noun \"report\"; the phrase \"along with several supporting appendices\" is a parenthetical addition that does not change the subject's number, so the singular verb \"was\" is correct."}, {"context": "Of the two proposals submitted, the second is far _____ than the first, offering clearer timelines and a more realistic budget.", "stem": "Which choice completes the sentence correctly?", "opts": ["more thoroughly", "thoroughest", "most thorough", "more thorough"], "ci": 3, "exp": "Because only two proposals are being compared, the comparative form \"more thorough\" is correct; the superlative \"most thorough\" is reserved for comparisons among three or more items, and \"more thoroughly\" is an adverb, not the needed adjective."}, {"context": "The new policy not only reduces paperwork for small business owners but also _____ the approval process for new permits.", "stem": "Which choice completes the sentence while maintaining parallel structure?", "opts": ["has simplified", "simplifying", "simplifies", "to simplify"], "ci": 2, "exp": "To maintain parallelism with \"reduces\" in the \"not only...but also\" construction, the second verb must also be a present-tense verb in the same form: \"simplifies.\""}, {"context": "The board recommended that the new policy _____ implemented immediately, despite some members' reservations.", "stem": "Which choice completes the sentence correctly?", "opts": ["will be", "is", "was", "be"], "ci": 3, "exp": "After a verb like \"recommended that,\" English requires the subjunctive mood, which uses the base form of the verb (\"be\") regardless of the subject."}, {"context": "The novel's author _____ a reclusive former journalist _____ rarely gives interviews.", "stem": "Which choice completes the sentence with the correct punctuation?", "opts": [", a reclusive former journalist,", "a reclusive former journalist", "; a reclusive former journalist;", ", a reclusive former journalist"], "ci": 0, "exp": "\"A reclusive former journalist\" is a nonrestrictive appositive that adds extra, non-essential information about the author, so it must be set off with a comma on both sides."}, {"context": "The three _____ presentations were postponed until next week because of a scheduling conflict.", "stem": "Which choice completes the sentence correctly?", "opts": ["manager's", "managers", "manager's'", "managers'"], "ci": 3, "exp": "Because there are three managers, each contributing a presentation, the plural possessive \"managers'\" is required. \"Manager's\" is singular possessive, and \"managers\" alone lacks the necessary possessive apostrophe."}, {"context": "By the time the committee finally reached a decision, the funding opportunity _____ already expired.", "stem": "Which choice completes the sentence with the correct verb form?", "opts": ["have", "had", "has", "was"], "ci": 1, "exp": "The funding opportunity expired before the committee reached its decision, an earlier past action relative to another past action, which requires the past perfect \"had expired.\""}, {"context": "The city council approved the new bike lanes after months of debate; _____, several local business owners have complained that the lanes reduce parking availability.", "stem": "Which choice completes the sentence with the most logical transition?", "opts": ["therefore", "for example", "similarly", "however"], "ci": 3, "exp": "The second clause presents a contrast to the approval described in the first clause (complaints following the approval), so the contrastive transition \"however\" is most logical."}, {"context": "Only the applications _____ arrive before the deadline will be considered for the scholarship.", "stem": "Which choice completes the sentence correctly?", "opts": ["that", "which", "whom", "who"], "ci": 0, "exp": "The clause is restrictive, meaning it is essential to identifying which applications are meant (only those arriving before the deadline), and no comma is used, so \"that\" is the correct choice rather than \"which,\" which is typically reserved for nonrestrictive clauses set off by commas."}, {"context": "Every student who submits the application late must resubmit _____ materials through the online portal.", "stem": "Which choice completes the sentence with the correct pronoun?", "opts": ["their", "his", "her", "its"], "ci": 0, "exp": "\"Their\" agrees with the indefinite antecedent \"every student\" without assuming a specific gender, unlike \"his\" or \"her,\" and \"its\" is used for non-human antecedents, not people."}, {"context": "The results were inconclusive, the researchers decided to repeat the experiment.", "stem": "Which choice provides the most effective way to punctuate or combine the two clauses?", "opts": ["The results were inconclusive, the researchers decided to repeat the experiment.", "The results were inconclusive the researchers decided to repeat the experiment.", "The results were inconclusive, however the researchers decided to repeat the experiment.", "The results were inconclusive, so the researchers decided to repeat the experiment."], "ci": 3, "exp": "Adding the coordinating conjunction \"so\" after the comma correctly joins the two independent clauses. The original sentence is a comma splice, removing the comma creates a run-on, and pairing a comma with \"however\" (a conjunctive adverb) still produces a comma splice."}, {"context": "Her fascination _____ ancient cryptography began when she discovered a coded letter in her grandmother's attic.", "stem": "Which choice completes the sentence with the correct preposition?", "opts": ["for", "with", "about", "toward"], "ci": 1, "exp": "The standard idiomatic pairing is \"fascination with\" a subject, not \"fascination about,\" \"for,\" or \"toward.\""}, {"context": "The chef refused to compromise on one ingredient _____ freshly cracked black pepper.", "stem": "Which choice completes the sentence with the correct punctuation?", "opts": [" ", ";", ",", ":"], "ci": 3, "exp": "A colon is the most effective way to introduce a specific example after a complete independent clause. A semicolon requires an independent clause on both sides, and a comma or no punctuation is too weak to introduce the example clearly."}, {"context": "The collection of rare manuscripts, donated by an anonymous alumnus decades ago, _____ housed in a climate-controlled wing of the library.", "stem": "Which choice completes the sentence with the correct verb?", "opts": ["are", "were", "is", "have been"], "ci": 2, "exp": "The subject of the sentence is the singular noun \"collection,\" not the plural noun \"manuscripts\" inside the intervening phrase, so it takes the singular verb \"is.\""}, {"context": "Even though the company reported record profits this quarter.", "stem": "Which choice corrects this sentence fragment?", "opts": ["The company reported record profits this quarter, even though.", "Even though the company reported record profits this quarter, its stock price fell sharply.", "Even though the company reported record profits this quarter.", "Even though, the company reported record profits this quarter."], "ci": 1, "exp": "The original sentence is a fragment because \"Even though...\" is a subordinate clause with no independent clause attached. Only the first choice adds an independent clause (\"its stock price fell sharply\") to complete the thought."}, {"context": "_____, the museum's newest exhibit finally opened to the public after a two-year renovation.", "stem": "Which choice most logically and clearly completes the sentence?", "opts": ["To delay repeatedly by supply shortages", "Having repeatedly delayed the supply shortages", "Delaying repeatedly due to supply shortages", "Delayed repeatedly by supply shortages"], "ci": 3, "exp": "The modifier should logically describe the exhibit itself, which was delayed by supply shortages. \"Delayed repeatedly by supply shortages\" correctly places the exhibit as the one being delayed, while the other choices illogically reverse the relationship or create a dangling modifier."}, {"context": "The corporation announced _____ plans to relocate its headquarters, a move that surprised even long-time employees.", "stem": "Which choice completes the sentence correctly?", "opts": ["it's", "its", "their", "its'"], "ci": 1, "exp": "\"Its\" is the correct possessive form here, with no apostrophe. \"It's\" is a contraction of \"it is,\" \"its'\" is not a valid word, and \"their\" is plural and does not agree with the singular \"corporation.\""}, {"context": "_____, the ancient bridge nonetheless remained structurally sound for centuries.", "stem": "Which choice most logically completes the sentence?", "opts": ["Built with simple stone arches and no mortar", "Having built simple stone arches and no mortar", "Building with simple stone arches and no mortar", "To build with simple stone arches and no mortar"], "ci": 0, "exp": "The modifier should describe the bridge, which was built with stone arches and no mortar. \"Built with simple stone arches and no mortar\" correctly and logically modifies \"the ancient bridge,\" while the other choices create illogical or dangling modifiers."}, {"context": "The internship taught her how to negotiate contracts, managing client accounts, and to present quarterly reports.", "stem": "Which choice most improves the parallel structure of the underlined portion?", "opts": ["how to negotiate contracts, manage client accounts, and present quarterly reports", "how negotiating contracts, managing client accounts, and presenting quarterly reports works", "how to negotiate contracts, managing client accounts, and to present quarterly reports", "negotiating contracts, to manage client accounts, and presenting quarterly reports"], "ci": 0, "exp": "All three items in the list should share the same grammatical form after \"how to.\" Only the first choice keeps all three verbs as parallel base forms: negotiate, manage, and present."}];var N = RAW_QUESTIONS.length;var ORDER_KEY = QUIZ_KEY + '_order_v1';
function shuffleArr(arr){
  var a = arr.slice();
  for(var i=a.length-1;i>0;i--){
    var j = Math.floor(Math.random()*(i+1));
    var t=a[i]; a[i]=a[j]; a[j]=t;
  }
  return a;
}
function identityOrder(){var o=[];for(var i=0;i<N;i++)o.push(i);return o;}
function isValidOrder(arr){
  if(!Array.isArray(arr) || arr.length===0) return false;
  for(var i=0;i<arr.length;i++){ if(typeof arr[i] !== 'number' || arr[i]<0 || arr[i]>=N) return false; }
  return true;
}
function loadOrder(){
  try{
    var raw = localStorage.getItem(ORDER_KEY);
    if(!raw) return null;
    var arr = JSON.parse(raw);
    if(!isValidOrder(arr)) throw new Error('bad');
    return arr;
  }catch(e){ try{localStorage.removeItem(ORDER_KEY);}catch(e2){} return null; }
}
function saveOrder(o){ try{ localStorage.setItem(ORDER_KEY, JSON.stringify(o)); }catch(e){} }

var order = loadOrder() || identityOrder();
if(!loadOrder()) saveOrder(order);
var pendingFreshMode = 'original';

function defaultState(){
  return { cur:0, answers:{}, showResults:false, timerTotalSec:null, timerStartedAt:null };
}
function loadState(){
  try{
    var raw = localStorage.getItem(QUIZ_KEY);
    if(!raw) return defaultState();
    var s = JSON.parse(raw);
    if(typeof s.cur !== 'number' || s.cur<0 || s.cur>=order.length) s.cur = 0;
    if(typeof s.answers !== 'object' || s.answers===null) s.answers = {};
    if(typeof s.showResults !== 'boolean') s.showResults = false;
    if(typeof s.timerTotalSec === 'undefined') s.timerTotalSec = null;
    if(typeof s.timerStartedAt === 'undefined') s.timerStartedAt = null;
    return s;
  }catch(e){ try{localStorage.removeItem(QUIZ_KEY);}catch(e2){} return defaultState(); }
}
function saveState(){ try{ localStorage.setItem(QUIZ_KEY, JSON.stringify(state)); }catch(e){} }

var state = loadState();
var timerInterval = null;

function getAttempts(){ try{ return parseInt(localStorage.getItem(ATT_KEY)||'0',10); }catch(e){ return 0; } }
function incAttempts(){ try{ localStorage.setItem(ATT_KEY, String(getAttempts()+1)); }catch(e){} }
function updateAttDisplay(){
  var el = document.getElementById('att-display');
  if(el) el.textContent = 'Total Attempts: ' + getAttempts();
}

function formatTime(sec){
  sec = Math.max(0, Math.round(sec));
  var m = Math.floor(sec/60), s = sec%60;
  return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
}
function renderTimer(){
  var setupEl = document.getElementById('timerSetup');
  var runningEl = document.getElementById('timerRunning');
  var dispEl = document.getElementById('timerDisplay');
  if(!setupEl||!runningEl||!dispEl) return;
  if(!state.timerStartedAt){ setupEl.style.display='flex'; runningEl.style.display='none'; return; }
  setupEl.style.display='none'; runningEl.style.display='flex';
  var elapsed = (Date.now()-state.timerStartedAt)/1000;
  var remaining = state.timerTotalSec - elapsed;
  dispEl.classList.remove('warn','danger');
  if(remaining<=0){ dispEl.textContent="Time's Up"; dispEl.classList.add('danger'); stopTimerInterval(); return; }
  dispEl.textContent = formatTime(remaining);
  if(remaining <= state.timerTotalSec*0.1) dispEl.classList.add('danger');
  else if(remaining <= state.timerTotalSec*0.25) dispEl.classList.add('warn');
}
function startTimer(){
  var input = document.getElementById('timerMinutesInput');
  var minutes = parseFloat(input.value);
  if(!minutes || minutes<=0) minutes=20;
  state.timerTotalSec = Math.round(minutes*60);
  state.timerStartedAt = Date.now();
  saveState(); renderTimer(); startTimerInterval();
}
function startTimerInterval(){ stopTimerInterval(); timerInterval=setInterval(renderTimer,1000); }
function stopTimerInterval(){ if(timerInterval){clearInterval(timerInterval); timerInterval=null;} }
function resetTimer(){
  state.timerTotalSec = null; state.timerStartedAt = null;
  stopTimerInterval(); saveState(); renderTimer();
}

function render(){
  updateAttDisplay();
  var qa = document.getElementById('quiz-area');
  var rs = document.getElementById('results-screen');
  if(state.showResults){
    qa.style.display='none';
    rs.classList.add('show');
    renderResults();
    return;
  }
  qa.style.display='block';
  rs.classList.remove('show');

  var qi = order[state.cur];
  var q = RAW_QUESTIONS[qi];
  document.getElementById('q-num').textContent = 'Q' + (state.cur+1) + ' / ' + order.length;

  var badge = document.getElementById('tag-badge');
  if(q.tag){
    badge.style.display='inline-block';
    badge.textContent = q.tag;
    badge.style.background = q.tagcolor || '#185FA5';
  } else { badge.style.display='none'; }

  var pbox = document.getElementById('passage-box');
  if(q.passage){ pbox.style.display='block'; pbox.innerHTML = q.passage; } else { pbox.style.display='none'; }
  var cbox = document.getElementById('context-box');
  if(q.context){ cbox.style.display='block'; cbox.innerHTML = q.context; } else { cbox.style.display='none'; }

  document.getElementById('q-text').innerHTML = q.stem;

  var answered = state.answers[qi];
  var optDiv = document.getElementById('options');
  optDiv.innerHTML='';
  q.opts.forEach(function(optText, idx){
    var btn = document.createElement('button');
    btn.className='opt-btn';
    btn.innerHTML = optText;
    btn.disabled = answered !== undefined;
    if(answered !== undefined){
      if(idx === q.ci) btn.classList.add(answered===idx ? 'correct' : 'revealed');
      else if(answered === idx) btn.classList.add('wrong');
    }
    btn.onclick = function(){ chooseAnswer(idx); };
    optDiv.appendChild(btn);
  });

  var expDiv = document.getElementById('exp-box');
  if(answered !== undefined && answered !== q.ci){
    expDiv.style.display='block';
    expDiv.innerHTML = q.exp;
  } else {
    expDiv.style.display='none';
  }

  var nextBtn = document.getElementById('next-btn');
  nextBtn.textContent = (state.cur >= order.length-1) ? 'Show Results →' : 'Next →';

  updateNav();
  if(window.postRenderHook) window.postRenderHook();

}

function updateNav(){
  var answered=0;
  for(var k=0;k<order.length;k++){ if(state.answers[order[k]]!==undefined) answered++; }
  document.getElementById('nav-count').textContent = answered + ' / ' + order.length;
  document.getElementById('prog-fill').style.width = (answered/order.length*100).toFixed(1)+'%';
  renderDots();
}
function renderDots(){
  var panel = document.getElementById('dot-panel');
  if(panel.style.display==='none') return;
  var html='';
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var bg = state.answers[qi]===undefined ? '#d7dde6' : (state.answers[qi]===RAW_QUESTIONS[qi].ci ? '#185FA5' : '#E24B4A');
    html += '<button class="dot" style="background:'+bg+';" onclick="goToQ('+pos+')">'+(pos+1)+'</button>';
  }
  var answered=0;
  for(var k=0;k<order.length;k++){ if(state.answers[order[k]]!==undefined) answered++; }
  if(answered===order.length){
    html += '<br><button class="results-pill" onclick="showResultsNow()">Results</button>';
  }
  panel.innerHTML = html;
}
function toggleJump(){
  var panel = document.getElementById('dot-panel');
  var btn = document.getElementById('jump-btn');
  if(panel.style.display==='none' || panel.style.display===''){
    panel.style.display='block'; btn.innerHTML='Hide &#9652;'; renderDots();
  } else {
    panel.style.display='none'; btn.innerHTML='Jump &#9662;';
  }
}
function goToQ(pos){
  state.cur = pos; state.showResults=false; saveState(); render();
}
function showResultsNow(){
  state.showResults = true; incAttempts(); saveState(); render(); reportResult();
}
function chooseAnswer(idx){
  var qi = order[state.cur];
  if(state.answers[qi] !== undefined) return;
  state.answers[qi] = idx;
  saveState(); render();
}
function goPrev(){
  if(state.cur>0){ state.cur--; saveState(); render(); }
}
function goNext(){
  if(state.cur < order.length-1){ state.cur++; saveState(); render(); }
  else { state.showResults=true; incAttempts(); saveState(); render(); reportResult(); }
}
function reportResult(){
  try{
    var correct=0, wrong=0, skipped=0;
    for(var pos=0; pos<order.length; pos++){
      var qi = order[pos];
      if(state.answers[qi]===undefined){ skipped++; continue; }
      if(state.answers[qi]===RAW_QUESTIONS[qi].ci) correct++; else wrong++;
    }
    var total = order.length;
    var childName = 'Unknown';
    if(TITLE.indexOf('[Sion]')===0) childName='Sion';
    else if(TITLE.indexOf('[Grant]')===0) childName='Grant';
    else if(TITLE.indexOf('[Both]')===0) childName='Both';
    else if(TITLE.indexOf('[Review]')===0) childName='Review';
    var payload = {
      child: childName,
      quizTitle: TITLE,
      quizKey: QUIZ_KEY,
      attemptNumber: getAttempts(),
      correct: correct, wrong: wrong, skipped: skipped, total: total,
      scorePercent: total>0 ? Math.round((correct/total)*1000)/10 : 0
    };
    fetch(REPORT_ENDPOINT, {
      method: 'POST',
      mode: 'no-cors',
      headers: {'Content-Type': 'text/plain;charset=utf-8'},
      body: JSON.stringify(payload)
    }).catch(function(){});
  }catch(e){}
}
function renderResults(){
  var correct=0, wrong=0, skipped=0;
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    if(state.answers[qi]===undefined){ skipped++; continue; }
    if(state.answers[qi]===RAW_QUESTIONS[qi].ci) correct++; else wrong++;
  }
  document.getElementById('results-score').textContent = correct+' correct, '+wrong+' wrong, '+skipped+' skipped - out of '+order.length;
  var grid = document.getElementById('results-grid');
  grid.innerHTML='';
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var card = document.createElement('div');
    if(state.answers[qi]===undefined){
      card.className='r-card skipped';
      card.textContent='Q'+(pos+1)+' Skip';
    } else {
      var ok = state.answers[qi]===RAW_QUESTIONS[qi].ci;
      card.className='r-card '+(ok?'correct':'wrong');
      card.textContent='Q'+(pos+1)+' '+(ok?'OK':'X');
    }
    (function(p){ card.onclick=function(){ state.showResults=false; state.cur=p; saveState(); render(); }; })(pos);
    grid.appendChild(card);
  }
}
function retryWrong(){
  var wrong=[];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    if(state.answers[qi]!==undefined && state.answers[qi]!==RAW_QUESTIONS[qi].ci){
      wrong.push(qi);
    }
  }
  if(wrong.length===0) return;
  wrong.forEach(function(qi){ delete state.answers[qi]; });
  order = wrong;
  saveOrder(order);
  state.cur=0; state.showResults=false;
  saveState(); render(); renderTimer();
}
function copyRes(){
  var lines=[TITLE+' Results'];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var a = state.answers[qi];
    var s='Q'+(pos+1)+': ';
    if(a===undefined) s+='Skipped';
    else s += (a===RAW_QUESTIONS[qi].ci ? 'Correct' : 'Wrong');
    lines.push(s);
  }
  var text = lines.join('\n');
  try{
    if(navigator.clipboard){ navigator.clipboard.writeText(text).catch(function(){}); }
    else { var ta=document.createElement('textarea'); ta.value=text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }
  }catch(e){}
}
function saveWrongAnswers(){
  var wrongItems=[];
  for(var pos=0; pos<order.length; pos++){
    var qi = order[pos];
    var a = state.answers[qi];
    if(a!==undefined && a!==RAW_QUESTIONS[qi].ci){
      var q = RAW_QUESTIONS[qi];
      wrongItems.push({ question: q.stem, yourAnswer: q.opts[a], correctAnswer: q.opts[q.ci], explanation: q.exp });
    }
  }
  var blob = new Blob([JSON.stringify({title:TITLE, wrongAnswers:wrongItems}, null, 2)], {type:'application/json'});
  var url = URL.createObjectURL(blob);
  var a2 = document.createElement('a');
  a2.href = url; a2.download = QUIZ_KEY + '_wrong.json';
  document.body.appendChild(a2); a2.click(); document.body.removeChild(a2);
  URL.revokeObjectURL(url);
}
function openFreshModal(mode){
  pendingFreshMode = mode;
  var t = document.getElementById('freshModalTitle');
  var m = document.getElementById('freshModalText');
  if(mode==='random'){
    t.textContent='Start Fresh (Random Order)?';
    m.textContent='Questions will be reshuffled into a new random order, and all progress will be cleared. This cannot be undone.';
  } else {
    t.textContent='Start Fresh (Original Order)?';
    m.textContent='Questions will return to their original order, and all progress will be cleared. This cannot be undone.';
  }
  document.getElementById('freshModal').classList.add('show');
}
function openFreshModalOriginal(){ openFreshModal('original'); }
function openFreshModalRandom(){ openFreshModal('random'); }
function closeFreshModal(){ document.getElementById('freshModal').classList.remove('show'); }
function confirmFresh(){
  order = (pendingFreshMode==='random') ? shuffleArr(identityOrder()) : identityOrder();
  saveOrder(order);
  state = defaultState();
  saveState();
  resetTimer();
  closeFreshModal();
  render();
  renderTimer();
}

window.startTimer=startTimer;
window.toggleJump=toggleJump;
window.goToQ=goToQ;
window.showResultsNow=showResultsNow;
window.chooseAnswer=chooseAnswer;
window.goPrev=goPrev;
window.goNext=goNext;
window.retryWrong=retryWrong;
window.copyRes=copyRes;
window.saveWrongAnswers=saveWrongAnswers;
window.openFreshModalOriginal=openFreshModalOriginal;
window.openFreshModalRandom=openFreshModalRandom;
window.closeFreshModal=closeFreshModal;
window.confirmFresh=confirmFresh;

render();
renderTimer();
if(state.timerStartedAt) startTimerInterval();

